css:
/* The back-to-top affordance the handoff specifies is fixed to the viewport.
   `position: fixed` is deliberately outside the node-style whitelist, so this
   is the one rule the design needs that site/ cannot express. It is pinned to
   node ids, which are stable across edits in the dashboard. */
[data-bz-node="totop-holder"]{position:fixed;bottom:24px;right:24px;z-index:60;width:auto;padding:0}
[data-bz-node="totop-holder"] .bz-row{display:block}
[data-bz-node="totop"] .bz-btns{margin:0}
[data-bz-node="totop"] .bz-btn{border-radius:var(--radius-chip);box-shadow:0 8px 20px rgba(0,0,0,.2)}
